/**
 * @suppress
 */
public object FfiConverterTypeImessageCore: FfiConverter<ImessageCore, Pointer> {

    override fun lower(value: ImessageCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): ImessageCore {
        return ImessageCore(value)
    }

    override fun read(buf: ByteBuffer): ImessageCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: ImessageCore) = 8UL

    override fun write(value: ImessageCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



