/**
 * Anything that can go wrong on the Rust side, flattened to one variant.
 *
 * UniFFI turns this into a Kotlin exception. The distinctions rustpush draws
 * between its error kinds don't change what the app does (every one of them
 * ends as "this didn't work, here's why"), so carrying the message across is
 * enough and keeps the generated bindings small.
 *
 * The field is `reason` rather than `message` on purpose: UniFFI turns error
 * variants into Kotlin exception subclasses, and a field called `message`
 * collides with `Throwable.message`, which fails to compile on the Kotlin
 * side with an overload ambiguity that points at generated code.
 */
sealed class CoreException: kotlin.Exception() {
    
    class Failure(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Failure(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Failure -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * What actually happened, once the protocol noise is stripped out.
 */
sealed class EventKind {
    
    data class Text(
        val `text`: kotlin.String, 
        val `subject`: kotlin.String?, 
        /**
         * GUID of the message being replied to, if this is a reply.
         */
        val `replyToId`: kotlin.String?, 
        /**
         * A screen or bubble effect identifier, e.g. `com.apple.MobileSMS.expressivesend.impact`.
         */
        val `effect`: kotlin.String?, 
        val `attachments`: List<AttachmentInfo>, 
        /**
         * True for SMS relayed through a paired iPhone rather than iMessage.
         */
        val `isSms`: kotlin.Boolean) : EventKind() {
        companion object
    }
    
    /**
     * A tapback. `reaction` is the emoji itself for emoji tapbacks, or one of
     * the six classic names (heart/like/dislike/laugh/emphasize/question).
     */
    data class Tapback(
        val `targetId`: kotlin.String, 
        val `targetPart`: kotlin.ULong, 
        val `reaction`: kotlin.String, 
        val `added`: kotlin.Boolean) : EventKind() {
        companion object
    }
    
    data class Edit(
        val `targetId`: kotlin.String, 
        val `targetPart`: kotlin.ULong, 
        val `newText`: kotlin.String) : EventKind() {
        companion object
    }
    
    data class Unsend(
        val `targetId`: kotlin.String, 
        val `targetPart`: kotlin.ULong) : EventKind() {
        companion object
    }
    
    data class Typing(
        val `active`: kotlin.Boolean) : EventKind() {
        companion object
    }
    
    /**
     * The other side read the conversation.
     */
    object Read : EventKind()
    
    
    /**
     * The other side's device acknowledged receipt.
     */
    object Delivered : EventKind()
    
    
    /**
     * The other side marked the conversation unread.
     */
    object MarkedUnread : EventKind()
    
    
    data class GroupRenamed(
        val `name`: kotlin.String) : EventKind() {
        companion object
    }
    
    data class ParticipantsChanged(
        val `participants`: List<kotlin.String>) : EventKind() {
        companion object
    }
    
    /**
     * A send failed after the fact. `code` is Apple's own status number.
     */
    data class SendFailed(
        val `targetId`: kotlin.String, 
        val `code`: kotlin.ULong) : EventKind() {
        companion object
    }
    
    /**
     * A recognised protocol message the app has no screen for yet. Kept as a
     * variant rather than dropped so the receive loop stays lossless and the
     * Kotlin side can log what it saw.
     */
    data class Unhandled(
        val `description`: kotlin.String) : EventKind() {
        companion object
    }
    

    
    companion object
}

