/**
 * Where a login attempt stopped.
 *
 * Apple's login is a state machine, not a single call: a correct password very
 * often lands on a 2FA step rather than on success. The app has to render a
 * different screen for each outcome, so the step is the return value instead of
 * an error.
 */
sealed class LoginStep {
    
    /**
     * Password accepted and no second factor needed.
     */
    object Complete : LoginStep()
    
    
    /**
     * A six-digit code was pushed to the account's trusted devices.
     */
    object NeedsDeviceCode : LoginStep()
    
    
    /**
     * The account is set up for SMS second factor instead of device codes.
     */
    data class NeedsSmsCode(
        val `phoneNumbers`: List<PhoneNumber>) : LoginStep() {
        companion object
    }
    
    /**
     * Apple wants something done in a browser (terms, account repair).
     */
    data class NeedsWebStep(
        val `url`: kotlin.String) : LoginStep() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeLoginStep : FfiConverterRustBuffer<LoginStep>{
    override fun read(buf: ByteBuffer): LoginStep {
        return when(buf.getInt()) {
            1 -> LoginStep.Complete
            2 -> LoginStep.NeedsDeviceCode
            3 -> LoginStep.NeedsSmsCode(
                FfiConverterSequenceTypePhoneNumber.read(buf),
                )
            4 -> LoginStep.NeedsWebStep(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LoginStep) = when(value) {
        is LoginStep.Complete -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is LoginStep.NeedsDeviceCode -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is LoginStep.NeedsSmsCode -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypePhoneNumber.allocationSize(value.`phoneNumbers`)
            )
        }
        is LoginStep.NeedsWebStep -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`url`)
            )
        }
    }

    override fun write(value: LoginStep, buf: ByteBuffer) {
        when(value) {
            is LoginStep.Complete -> {
                buf.putInt(1)
                Unit
            }
            is LoginStep.NeedsDeviceCode -> {
                buf.putInt(2)
                Unit
            }
            is LoginStep.NeedsSmsCode -> {
                buf.putInt(3)
                FfiConverterSequenceTypePhoneNumber.write(value.`phoneNumbers`, buf)
                Unit
            }
            is LoginStep.NeedsWebStep -> {
                buf.putInt(4)
                FfiConverterString.write(value.`url`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceString: FfiConverterRustBuffer<List<kotlin.String>> {
    override fun read(buf: ByteBuffer): List<kotlin.String> {
        val len = buf.getInt()
        return List<kotlin.String>(len) {
            FfiConverterString.read(buf)
        }
    }

    override fun allocationSize(value: List<kotlin.String>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterString.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<kotlin.String>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterString.write(it, buf)
        }
    }
}




